<template><view class="page"><view class="user"><view class="avatar">{{initial}}</view><view><text class="name">{{auth.username||'管理员'}}</text><text class="server">服务节点：{{auth.serverId||'-'}}</text></view></view><view class="menu"><view class="row" @click="openProxy"><text>拉流代理</text><text class="arrow">›</text></view><view class="row"><text>当前版本</text><text class="value">0.1.0 H5</text></view></view><button class="logout" @click="confirmLogout">退出登录</button></view></template>
<script setup lang="ts">
import{computed}from'vue';import{onShow}from'@dcloudio/uni-app';import{useAuthStore}from'@/stores/auth';const auth=useAuthStore();const initial=computed(()=>auth.username?.slice(0,1).toUpperCase()||'W');onShow(()=>auth.requireAuth());function openProxy(){uni.navigateTo({url:'/pages/proxy/index'})}function confirmLogout(){uni.showModal({title:'退出登录',content:'确定要退出当前账号吗？',success:r=>{if(r.confirm)auth.signOut()}})}
</script><style scoped>
.page{min-height:100vh;padding:28rpx 24rpx;box-sizing:border-box}.user{display:flex;align-items:center;gap:24rpx;padding:38rpx 32rpx;color:#fff;background:linear-gradient(135deg,#2368f2,#5d8ff5);border-radius:26rpx}.avatar{width:100rpx;height:100rpx;background:rgba(255,255,255,.2);border:2rpx solid rgba(255,255,255,.5);border-radius:50%;text-align:center;line-height:100rpx;font-size:42rpx;font-weight:700}.name,.server{display:block}.name{font-size:35rpx;font-weight:600}.server{margin-top:12rpx;opacity:.8;font-size:23rpx}.menu{margin-top:24rpx;background:#fff;border-radius:24rpx;overflow:hidden}.row{display:flex;justify-content:space-between;padding:30rpx;border-bottom:1rpx solid #edf0f4;font-size:28rpx}.arrow,.value{color:#939caf}.logout{margin-top:40rpx;color:#d84b4b;background:#fff;border-radius:20rpx}
</style>
